CREATE TABLE "user_roles" (
    "user_role_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" VARCHAR(50) NOT NULL,
    UNIQUE ("name")
);
CREATE TABLE "services" (
    "service_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" VARCHAR(100) NOT NULL,
    "unit" VARCHAR(20) NOT NULL,
    "tariff" DECIMAL(10,2) NOT NULL,
    UNIQUE ("name")
);
CREATE TABLE "payment_methods" (
    "method_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" VARCHAR(50) NOT NULL,
    UNIQUE ("name")
);
CREATE TABLE "users" (
    "user_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "login" VARCHAR(50) NOT NULL,
    "password" VARCHAR(100) NOT NULL,
    "full_name" VARCHAR(150) NOT NULL,
    "address" VARCHAR(200),
    "user_role" INTEGER NOT NULL,
    FOREIGN KEY ("user_role") REFERENCES "user_roles" ("user_role_id"),
    UNIQUE ("login")
);
CREATE TABLE "accruals" (
    "accrual_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "resident_id" INTEGER NOT NULL,
    "service_id" INTEGER NOT NULL,
    "accountant_id" INTEGER NOT NULL,
    "period" VARCHAR(7) NOT NULL,
    "volume" DECIMAL(10,2) NOT NULL,
    "amount" DECIMAL(10,2) NOT NULL,
    FOREIGN KEY ("resident_id") REFERENCES "users" ("user_id"),
    FOREIGN KEY ("service_id") REFERENCES "services" ("service_id"),
    FOREIGN KEY ("accountant_id") REFERENCES "users" ("user_id")
);
CREATE TABLE "payments" (
    "payment_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "accrual_id" INTEGER NOT NULL,
    "method_id" INTEGER NOT NULL,
    "amount" DECIMAL(10,2) NOT NULL,
    "payment_date" DATE NOT NULL,
    "status" VARCHAR(20) DEFAULT 'confirmed' NOT NULL,
    FOREIGN KEY ("accrual_id") REFERENCES "accruals" ("accrual_id"),
    FOREIGN KEY ("method_id") REFERENCES "payment_methods" ("method_id")
);
CREATE TABLE "receipts" (
    "receipt_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "payment_id" INTEGER NOT NULL,
    "number" VARCHAR(20) NOT NULL,
    "issue_date" DATE NOT NULL,
    FOREIGN KEY ("payment_id") REFERENCES "payments" ("payment_id"),
    UNIQUE ("payment_id"),
    UNIQUE ("number")
);